let v = inputData.labels;

// If empty, undefined, or "No data"
if (!v || v === "No data") {
  // Dummy value that will never match a real tag
  return { cleaned: ["__NO_LABEL__"] };
}

// Already a line item array
if (Array.isArray(v)) {
  return {
    cleaned: v
      .map(x => String(x).trim())
      .filter(Boolean)
  };
}

// Comma-separated string
return {
  cleaned: String(v)
    .split(",")
    .map(x => x.trim())
    .filter(Boolean)
};

// Normalize both inputs to arrays
let types = inputData.types;
let urls = inputData.urls;

// Handle if Zapier sends them as comma-separated strings instead of arrays
if (typeof types === 'string') types = types.split(',');
if (typeof urls === 'string') urls = urls.split(',');

// Ensure both are arrays
if (!Array.isArray(types)) types = [types];
if (!Array.isArray(urls)) urls = [urls];

const rows = [];

for (let i = 0; i < types.length; i++) {
  const type = (types[i] || '').trim();
  const url = (urls[i] || '').trim();
  if (type && url) {
    rows.push(`| ${type} | ${url} |`);
  }
}

return { tableRows: rows.join('\n') };

// Utility to normalize inputs into arrays
const toArray = v => 
  Array.isArray(v) ? v 
  : typeof v === "string" ? v.split(",") 
  : [];

const names = toArray(inputData.product_names);
const colors = toArray(inputData.product_colors);
const links = toArray(inputData.product_links);
const imprintMethods = toArray(inputData.imprint_methods);
const imprintColors = toArray(inputData.imprint_colors);
const locations = toArray(inputData.decoration_locations);
const sizes = toArray(inputData.decoration_sizes);
const infos = toArray(inputData.other_info);

const result = [];

for (let i = 0; i < names.length; i++) {
  const name = (names[i] || "").trim();
  if (!name) continue;

  const color = (colors[i] || "").trim();
  const link = (links[i] || "").trim();
  const method = (imprintMethods[i] || "").trim();
  const imprintColor = (imprintColors[i] || "").trim();
  const location = (locations[i] || "").trim();
  const size = (sizes[i] || "").trim();
  const info = (infos[i] || "").trim();

  result.push(
`**${name}**
• Color: ${color}
• Imprint Method: ${method}
• Imprint Color: ${imprintColor}
• Location: ${location}
• Size: ${size}
• Link: ${link}
• Notes: ${info}`
  );
}

// Join all with blank lines between each product
return { productDetails: result.join("\n\n") };

// Normalize helper
const toArray = v =>
  Array.isArray(v) ? v
  : typeof v === "string" ? v.split(",")
  : [];

// Inputs (map these to your Zap fields)
const slideTitles = toArray(inputData.slide_titles);
const productTitles = toArray(inputData.product_titles);
const productLinks = toArray(inputData.product_links);

// Group products by slide
const slides = {};

for (let i = 0; i < slideTitles.length; i++) {
  const slideTitle = (slideTitles[i] || '').trim();
  const productTitle = (productTitles[i] || '').trim();
  const productLink = (productLinks[i] || '').trim();

  if (!slideTitle || !productTitle) continue;

  if (!slides[slideTitle]) slides[slideTitle] = [];

  slides[slideTitle].push({
    title: productTitle,
    link: productLink
  });
}

// Build markdown output
const rows = [];

for (const [slideTitle, products] of Object.entries(slides)) {
  rows.push(`**${slideTitle}**`);

  for (const p of products) {
    rows.push(`• [${p.title}](${p.link})`);
  }

  // Add a blank line between slides
  rows.push('');
}

// Final combined output
return { presentationTable: rows.join('\n') };

// Normalize helper
const toArray = v =>
  Array.isArray(v) ? v
  : typeof v === "string" ? v.split(",")
  : [];

// Inputs (map these in Zapier)
const marketingCollateral = toArray(inputData.marketing_collateral);
const marketingLinks = toArray(inputData.marketing_links);
const trendShops = toArray(inputData.trend_shops);
const trendLinks = toArray(inputData.trend_links);

const rows = [];

// MARKETING COLLATERAL SECTION
const hasMarketing = marketingCollateral.some(c => (c || '').trim());
if (hasMarketing) {
  rows.push(`**Marketing Collateral**`);
  for (let i = 0; i < marketingCollateral.length; i++) {
    const title = (marketingCollateral[i] || '').trim();
    const link = (marketingLinks[i] || '').trim();
    if (title && link) rows.push(`• [${title}](${link})`);
  }
  rows.push(''); // blank line after section
}

// TREND SHOPS SECTION
const hasTrends = trendShops.some(t => (t || '').trim());
if (hasTrends) {
  rows.push(`**Trend Shops**`);
  for (let i = 0; i < trendShops.length; i++) {
    const title = (trendShops[i] || '').trim();
    const link = (trendLinks[i] || '').trim();
    if (title && link) rows.push(`• [${title}](${link})`);
  }
  rows.push('');
}

// Return only if there's content
if (rows.length === 0) {
  return { additionalContent: '' };
}

return { additionalContent: rows.join('\n') };

let label = inputData.client_label || "";
let name = inputData.client_name || "";

return {
  taskName: label === "Not Listed" ? name : label
};

